import { USERS, expect, test } from "../../fixtures";

test("wrong password is rejected with 401 invalid_credentials", { tag: "@AUTH-02" }, async ({ request }) => {
  // Act
  const response = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: "wrong-password" },
  });

  // Assert
  expect(response.status(), await response.text()).toBe(401);
  const body = await response.json();
  expect(body.error.code, JSON.stringify(body)).toBe("invalid_credentials");
});
